SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0510000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 51, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "51", "printedPageNumber": 51, "pdfPageNumber": 434, "sequenceIndex": 41, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0510100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith II", "sourceIdentifier": "II", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0510000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (a)—Rewards of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "in His word; and who realize the value of the blessings and reward in the Hereafter. It is in respect of such people that Allah says:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "رِجَالٌ لَا تُلْهِيهِمْ تِجَارَةٌ وَلَا بَيْعٌ عَنْ ذِكْرِ اللَّهِ وَإِقَامِ الصَّلَاةِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Men, whom neither merchandise nor sale beguileth them from remembrance of Allah and constancy in ''salaat.''\" (XXIV: 37).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said of Saalim Haddaad (Rahmatullah alaih) (a trader and a great Soofi) that on hearing Azaan he would turn pale and grow restless. He would stand up immediately, leaving his shop open and recite these couplets:-\n\n1. \"When Thy summoner stands up to summon,\nquickly I stand up.\nTo respond to (the summons of) The Mighty Lord\nWho hath no peer.\"\n\n2. \"I reply to the summons with complete submission and cheer,\n''Here am I, O Bountiful One.''\"\n\n3. \"My face grows pale with awe and fear, and occupation in Thee distracts me from all other occupations.\"\n\n4. \"I swear by Thee, naught is dear to me save Thy remembrance.\nNothing is more ravishing for me than Thy sweet name.\"\n\n5. \"O, will there be a time for us to be together?\nA lover is happy only when he is with his love.\"\n\n6. \"He whose eyes have seen the light of Thy Beauty\nCan never be solaced. He must die yearning for Thee.\"\n\nIt is said in a hadith: \"People frequenting the musjid are its pegs (dwellers). Angels are their companions and visit them when they are sick and help them when they are at their jobs.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510500-0000-4000-8000-000000000001", "structuralNodeId": "b0510100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith II", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510600-0000-4000-8000-000000000001", "structuralNodeId": "b0510100-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن أبي هريرة رضي الله عنه قال قال رسول الله ﷺ صلاة الرجل في جماعة تضعف على صلاته في بيته وفي سوقه خمساً وعشرين ضعفاً وذلك أنه إذا", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}]}'::jsonb);